 @Override protected void onCreate(Bundle b){ThemePalette.applyActivityTheme(this);super.onCreate(b);prefs=getSharedPreferences("chat",MODE_PRIVATE);applyPalette();mode=getIntent().getStringExtra("mode");welcomeUri=b==null?prefs.getString("welcomeImageUri",""):b.getString("welcomeImageUri","");welcomeShape=b==null?prefs.getString("welcomeImageShape","circle"):b.getString("welcomeImageShape","circle");welcomeDisplayMode=b==null?(HomeCopy.isIconMode(prefs)?"icon":"text"):b.getString(HomeCopy.WELCOME_DISPLAY_MODE,"text");draft=b;setContentView(build());}
