 private View build(){LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(page);LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(12),dp(10),dp(16),dp(8));TextView back=icon("‹",32);back.setOnClickListener(v->finish());bar.addView(back,new LinearLayout.LayoutParams(dp(44),dp(44)));bar.addView(text(title(),21,ink,true),new LinearLayout.LayoutParams(0,-2,1));root.addView(bar,new LinearLayout.LayoutParams(-1,dp(ScreenInsets.TOP_BAR_DP)));ScrollView s=new ScrollView(this);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(dp(18),dp(6),dp(18),dp(28));if("search".equals(mode))search(body);else if("theme".equals(mode))theme(body);else if("conversation".equals(mode))conversation(body);else topic(body);s.addView(body);root.addView(s,new LinearLayout.LayoutParams(-1,0,1));ScreenInsets.apply(this,root);return root;}
