 private void conversation(LinearLayout b){TextView hint=text("以下是新对话的默认值。已有对话可在历史长按菜单中的「对话设置」单独调整；不支持采样的模型不会发送温度与 Top P。",13,muted,false);b.addView(hint);ModelStore.migrate(prefs);EditText temp=field(prefs.getString("conversationTemperature","0.7")),top=field(prefs.getString("conversationTopP","0.9")),prompt=field(prefs.getString("systemPrompt",""));prompt.setSingleLine(false);prompt.setMinLines(3);labelledConversation(b,"温度（0..2）",temp);labelledConversation(b,"Top P（0..1）",top);labelledConversation(b,"初始系统提示词（默认空）",prompt);save(b,()->{try{ModelStore.range(temp.getText().toString(),2);}catch(Exception e){temp.setError("请输入 0..2 的数值");saveAccepted=false;return;}try{ModelStore.range(top.getText().toString(),1);}catch(Exception e){top.setError("请输入 0..1 的数值");saveAccepted=false;return;}prefs.edit().putString("conversationTemperature",temp.getText().toString()).putString("conversationTopP",top.getText().toString()).putString("systemPrompt",prompt.getText().toString()).apply();});}
