  EditText key=field(draft==null?prefs.getString("tavilyKey",""):draft.getString("searchKeyDraft",prefs.getString("tavilyKey",""))),depth=field(draft==null?prefs.getString("tavilyDepth","basic"):draft.getString("searchDepthDraft",prefs.getString("tavilyDepth","basic"))),count=field(draft==null?prefs.getString("tavilyCount","5"):draft.getString("searchCountDraft",prefs.getString("tavilyCount","5")));searchKeyField=key;searchDepthField=depth;searchCountField=count;
